python3 -c $'import json,sys\nC=lambda x:x or sys.exit(\'BLOCKED\')\nx=json.load(sys.stdin)\nC(x.get(\'source\')==\'SYNTHETIC\' and x.get(\'mode\')==\'paper\' and all(x.get(k) is False for k in (\'network\',\'order_submission\',\'live_armed\',\'execute_external\')))\nn=x.get(\'max_steps\');C(type(n)==int and 1<=n<=512)\nm=x[\'machine\'];C(len(m)==6)\na=m[\'alphabet\'];C(type(a)==list and 1<=len(a)<=16 and all(type(s)==str and 1<=len(s)<=12 for s in a) and len(set(a))==len(a))\nb=m[\'blank\'];q=m[\'start\'];h=m[\'halt\'];C(b in a and type(q)==str and type(h)==str and q!=h)\nw=m[\'input\'];C(type(w)==list and len(w)<=64 and all(s in a for s in w))\nt=m[\'rules\'];C(type(t)==list and 1<=len(t)<=128)\nf={}\nfor z in t:\n C(type(z)==list and len(z)==5)\n u,v,y,d,k=z;C(type(u)==str and type(k)==str and u!=h and v in a and y in a and d in \'LRS\' and len(d)==1)\n C((u,v) not in f);f[u,v]=y,d,k\nC(q in {u for u,v in f})\np=[];j=2\nwhile len(p)<256:\n if all(j%d for d in p if d*d<=j):p.append(j)\n j+=1\nv={z:i for i,z in enumerate(p)};s=json.dumps(m,ensure_ascii=False,sort_keys=True,separators=(\',\',\':\')).encode();C(len(s)<=8192)\ng=1\nfor c in s:g=g*2048+p[c]\nz=g;out=[]\nwhile z>1:\n z,c=divmod(z,2048);C(c in v);out.append(v[c])\nC(bytes(out[::-1])==s)\nT={i:c for i,c in enumerate(w) if c!=b};i=count=0;state=q\nwhile count<n and state!=h:\n k=state,T.get(i,b)\n if k not in f:break\n y,d,state=f[k]\n if y==b:T.pop(i,None)\n else:T[i]=y\n i+=(d==\'R\')-(d==\'L\');count+=1;C(abs(i)<=1024 and len(T)<=1024)\nstatus=\'HALTED\' if state==h else \'STUCK\' if (state,T.get(i,b)) not in f else \'STEP_LIMIT\'\nprint(json.dumps(dict(version=\'G16\',status=status,state=state,steps=count,head=i,nonblank_cells=sorted([[j,c] for j,c in T.items()]),godel_roundtrip=True,godel_identity=1,descriptor_bytes=len(s),descriptor_godel_digits=len(str(g)),orders_submitted=0,live_allowed=False,halting_oracle=False,god_identity_proved=False,certified_as_real_trading=False),sort_keys=True))' "$@"
